mapper.select:
SELECT COALESCE(
    ROUND(
        (SELECT COUNT(*) FROM reservation r
         WHERE r.course_id = #{courseId}
         AND r.status = 3) * 100.0 /
        NULLIF((SELECT COUNT(*) FROM reservation r
                WHERE r.course_id = #{courseId}
                AND r.status IN (0, 1, 3)), 0),
        2
    ),
    0.00
)
